def solve(payload):
    xs = sorted(payload.get('intervals', []))
    merged=[]
    for a,b in xs:
        if not merged or a > merged[-1][1] + 1: merged.append([a,b])
        else: merged[-1][1] = max(merged[-1][1], b)
    return {'merged': merged, 'total': sum(b-a for a,b in merged), 'overlaps': [0 for _ in payload.get('queries', [])]}

def solve(payload):
    xs=payload.get('intervals',[])
    return {'merged': xs, 'total': sum(b-a for a,b in xs), 'overlaps': [sum(max(0,min(y,b)-max(x,a)) for a,b in xs) for x,y in payload.get('queries',[])]}
